using AdDatabase.API.DTOs;using AdDatabase.API.Extensions;using AdDatabase.BLL.Entities;using AdDatabase.BLL.Interfaces;using AdDatabase.BLL.Models;using AutoMapper;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace AdDatabase.API.Controllers;[ApiController,Route("api/ads")]public class AdsController(IAdService service,IMapper mapper):ControllerBase{[HttpGet]public async Task<IActionResult>List([FromQuery]AdFilter f,CancellationToken ct)=>Ok(ApiResponse<PagedResult<Ad>>.Ok(await service.SearchAsync(f,ct)));[HttpGet("{id:int}")]public async Task<IActionResult>Get(int id,CancellationToken ct)=>Ok(ApiResponse<AdDetailsResponseDto>.Ok(mapper.Map<AdDetailsResponseDto>(await service.GetAsync(id,ct))));[Authorize,HttpPost]public async Task<IActionResult>Create(CreateAdDto d,CancellationToken ct){var a=await service.CreateAsync(User.UserId(),mapper.Map<CreateAdRequest>(d),ct);return CreatedAtAction(nameof(Get),new{id=a.Id},ApiResponse<Ad>.Ok(a,"Ad created"));}[Authorize,HttpPut("{id:int}")]public async Task<IActionResult>Update(int id,UpdateAdDto d,CancellationToken ct)=>Ok(ApiResponse<Ad>.Ok(await service.UpdateAsync(User.UserId(),id,mapper.Map<UpdateAdRequest>(d),ct),"Ad updated"));[Authorize,HttpDelete("{id:int}")]public async Task<IActionResult>Delete(int id,CancellationToken ct){await service.DeleteAsync(User.UserId(),id,ct);return Ok(ApiResponse<object>.Ok(new{},"Ad deleted"));}}
